#!/usr/bin/env bash
# Regenerates rust/lychee-sys/src/bindings.rs from lychee.h. Run it after
# changing the header; the file is checked in so that building the crates
# needs no libclang. Needs bindgen (cargo install bindgen-cli).
set -euo pipefail

root="$(cd "$(dirname "$0")/.." && pwd)"

bindgen "$root/core/include/lychee/lychee.h" \
  --output "$root/rust/lychee-sys/src/bindings.rs" \
  --allowlist-item '(lychee|LYCHEE)_.*' \
  --blocklist-item 'LYCHEE_LYCHEE_H_' \
  --default-enum-style consts \
  --no-prepend-enum-name \
  --no-layout-tests \
  --use-core \
  --raw-line '// Generated by tool/rust_bindings.sh from core/include/lychee/lychee.h.' \
  --raw-line '// Do not edit.'
